use anyhow::{anyhow, Context, Ok, Result};
use curv::arithmetic::Converter;
use curv::BigInt;
use futures::{SinkExt, StreamExt, TryStreamExt};

use multi_party_ecdsa::protocols::multi_party_ecdsa::gg_2020::state_machine::sign::{
    OfflineStage, SignManual,
};
use round_based::async_runtime::AsyncProtocol;
use round_based::Msg;
use serde_json::json;

use crate::ecdsa::gg_2020::sm_client::join_computation;

#[allow(dead_code)]
pub async fn sign(
    share_key: &str,
    parties: Vec<u16>,
    message: &str,
    address: surf::Url,
    room_id: &str,
) -> Result<String, anyhow::Error> {
    let number_of_parties = parties.len();
    let local_share = serde_json::from_slice(&share_key.as_bytes()).context("parse local share")?;

    let (i, incoming, outgoing) =
        join_computation(address.clone(), &format!("{}-offline", room_id))
            .await
            .context("join offline computation")?;

    let incoming = incoming.fuse();
    tokio::pin!(incoming);
    tokio::pin!(outgoing);

    let signing = OfflineStage::new(i, parties, local_share)?;
    let completed_offline_stage = AsyncProtocol::new(signing, incoming, outgoing)
        .run()
        .await
        .map_err(|e| anyhow!("protocol execution terminated with error: {}", e))?;

    let (_i, incoming, outgoing) = join_computation(address, &format!("{}-online", room_id))
        .await
        .context("join online computation")?;

    tokio::pin!(incoming);
    tokio::pin!(outgoing);

    let (signing, partial_signature) = SignManual::new(
        BigInt::from_bytes(message.as_bytes()),
        completed_offline_stage,
    )?;

    outgoing
        .send(Msg {
            sender: i,
            receiver: None,
            body: partial_signature,
        })
        .await?;

    let partial_signatures: Vec<_> = incoming
        .take(number_of_parties - 1)
        .map_ok(|msg| msg.body)
        .try_collect()
        .await?;
    let sig = signing
        .complete(&partial_signatures)
        .context("online stage failed")?;
    // let signature = serde_json::to_string(&signature).context("serialize signature")?;

    let signature = json!({
        "r": BigInt::from_bytes(sig.r.to_bytes().as_ref()).to_str_radix(16),
        "s": BigInt::from_bytes(sig.s.to_bytes().as_ref()).to_str_radix(16),
        "v": sig.recid.clone(),
    })
    .to_string();

    Ok(signature)
}

